// One path of unit squares: crisp at any whole zoom, and the color is the text's (fill: currentColor in .pxi).
function crunchyIcon(name) {
  const rows = CRUNCHY_ICONS[name];
  if (!rows) return null;
  const NS = "http://www.w3.org/2000/svg";
  const svg = document.createElementNS(NS, "svg");
  svg.setAttribute("class", "pxi");
  svg.setAttribute("viewBox", "0 0 " + rows[0].length + " " + rows.length);
  svg.setAttribute("aria-hidden", "true");
  svg.setAttribute("data-key", name);
  let d = "";
  rows.forEach(function (r, y) {
    for (let x = 0; x < r.length; x++) if (r[x] === "#") d += "M" + x + " " + y + "h1v1h-1z";
  });
  const path = document.createElementNS(NS, "path");
  path.setAttribute("d", d);
  svg.appendChild(path);
  return svg;
}

// Every [data-icon] element in root, ROOT ITSELF INCLUDED, gets its icon as the first child. Safe to call again, and
// AFTER CHANGING data-icon: an icon whose key differs is replaced (a toggle: lock/unlock, play/pause), and one whose
// name is no longer known is removed. (Build 4, from CrunchyUI's first adoption: handed the button itself it used to
// match nothing, and a changed data-icon kept the old mark; both failed silently, by doing less.)
function crunchyIconsApply(root) {
  root = root || document;
  const els = Array.prototype.slice.call(root.querySelectorAll("[data-icon]"));
  if (root.matches && root.matches("[data-icon]")) els.unshift(root);
  els.forEach(function (el) {
    const key = el.getAttribute("data-icon"), old = el.firstElementChild;
    const has = old && old.classList.contains("pxi") ? old : null;
    if (has && has.getAttribute("data-key") === key) return;
    const svg = crunchyIcon(key);
    if (has) el.removeChild(has);
    if (svg) el.insertBefore(svg, el.firstChild);
  });
}
